const fs = require('node:fs'), path = require('node:path'), assert = require('node:assert/strict');
const { buildSync } = require('esbuild'), Module = require('node:module');
const result = buildSync({ entryPoints: ['src/scene.ts'], bundle: true, platform: 'node', format: 'cjs', packages: 'external', write: false, logLevel: 'silent' });
const filename = path.join(process.cwd(), '__scene-check.cjs'), compiled = new Module(filename);
compiled.paths = Module._nodeModulePaths(process.cwd());
compiled._compile(result.outputFiles[0].text, filename);
const { WallView } = compiled.exports, THREE = require('three');
const { createHoldModel } = require('./src/hold-models.ts');
const { tryPlacementFrame } = require('./src/placement-geometry.ts');
const { registerHoldAssetLibrary } = require('./src/hold-assets.ts');
registerHoldAssetLibrary(JSON.parse(fs.readFileSync('../assets/holds/library.json', 'utf8')));
const bundle = JSON.parse(fs.readFileSync('../fixtures/setting-diagonal_balance-bundle.json', 'utf8'));
const view = Object.create(WallView.prototype);
Object.assign(view, { request: bundle.request, candidate: bundle.candidates[0], camera: new THREE.PerspectiveCamera(34, .53, .01, 100), controls: { minDistance: .35, target: new THREE.Vector3(0, 1.5, 0) }, holdGroups: new Map() });
view.camera.position.set(2.9, 2.25, 5.25);
const context = { angleDeg: bundle.request.scene.angle_deg, inventory: bundle.request.scene.inventory, wallPanels: bundle.request.scene.wall_panels, placements: view.candidate.placements };
const holds = new Map(bundle.request.scene.inventory.map(h => [h.id, h]));
for (const p of view.candidate.placements) {
  const h = holds.get(p.inventory_id), frame = tryPlacementFrame(p, context);
  if (!h || !frame) continue;
  const group = createHoldModel(h, { id: p.id });
  view.applyFrame(group, frame); view.holdGroups.set(p.id, group);
}
const direction = new THREE.Vector3(.28, .1, .955).normalize();
const route = view.portraitRouteBounds(), target = view.wallTarget(), distance = view.fitDistance(direction);
view.camera.position.copy(target).addScaledVector(direction, distance);
view.camera.lookAt(target); view.camera.updateMatrixWorld(); view.camera.updateProjectionMatrix();
let maximum = 0;
for (const x of [route.min.x, route.max.x]) for (const y of [route.min.y, route.max.y]) for (const z of [route.min.z, route.max.z]) {
  const screen = new THREE.Vector3(x, y, z).project(view.camera);
  maximum = Math.max(maximum, Math.abs(screen.x), Math.abs(screen.y));
  assert.ok(Math.abs(screen.x) <= 1 && Math.abs(screen.y) <= 1, 'route envelope inside portrait viewport');
}
view.camera.aspect = 1.2;
const desktop = view.fitDistance(direction);
assert.equal(view.portraitRouteBounds(), undefined, 'desktop whole-wall fit unchanged');
const pick = Object.create(WallView.prototype), scene = new THREE.Scene(), wallGroup = new THREE.Group(), camera = new THREE.PerspectiveCamera(34, 1, .01, 100);
camera.position.set(0, 0, 5); camera.lookAt(0, 0, 0); camera.updateProjectionMatrix(); scene.add(wallGroup);
const hold = new THREE.Mesh(new THREE.BoxGeometry(.03, .03, .03), new THREE.MeshBasicMaterial()), group = new THREE.Group();
hold.userData = { id: 'tiny', resin: true }; group.add(hold); wallGroup.add(group);
Object.assign(pick, { scene, wallGroup, camera, pickables: [hold], holdGroups: new Map([['tiny', group]]), raycaster: new THREE.Raycaster(), renderer: { domElement: { getBoundingClientRect: () => ({ left: 0, top: 0, width: 400, height: 400 }) } } });
assert.equal(pick.nearestVisibleHold({ clientX: 210, clientY: 200 }), 'tiny', 'near miss selects tiny visible hold');
assert.equal(pick.nearestVisibleHold({ clientX: 213, clientY: 200 }), undefined, 'outside 12px does not select');
group.visible = false;
assert.equal(pick.nearestVisibleHold({ clientX: 200, clientY: 200 }), undefined, 'hidden hold never selected');
group.visible = true;
const blocker = new THREE.Mesh(new THREE.BoxGeometry(.2, .2, .03), new THREE.MeshBasicMaterial());
blocker.position.z = .5; wallGroup.add(blocker);
assert.equal(pick.nearestVisibleHold({ clientX: 210, clientY: 200 }), undefined, 'occluded hold never selected');
console.log(JSON.stringify({ status: 'pass', portrait_distance_m: distance, desktop_distance_m: desktop, max_route_ndc: maximum, checks: ['padded route envelope inside portrait view', 'desktop whole-wall fit unchanged', '12px near miss selects visible hold', 'outside radius ignored', 'hidden hold ignored', 'occluded hold ignored'] }, null, 2));
